#include <bits/stdc++.h>
using namespace std;

using i32 = int;
using i64 = long long;

const i32 MAXN = 100010;
const i32 MAXM = 2000020;
const i64 INF = 1000000000;

struct Edge {
    i32 next, to, cap;
    i64 cost;
} edge[MAXM];

i32 head[MAXN], ecnt = 1, node_cnt;
vector<i32> graph[MAXN];

void connect(i32 u, i32 v, i32 cap, i64 cost) {
    edge[++ecnt] = {head[u], v, cap, cost};
    head[u] = ecnt;
    edge[++ecnt] = {head[v], u, 0, -cost};
    head[v] = ecnt;
}

namespace MinCostFlow {
    i32 cur[MAXN];
    bool visited[MAXN];
    i64 dist[MAXN], tag[MAXN];

    struct HeapNode {
        i32 id;
        i64 key;
        HeapNode(i32 i = 0, i64 k = 0) : id(i), key(k) {}
        bool operator<(const HeapNode& other) const {
            return key > other.key;
        }
    };

    priority_queue<HeapNode> pq;

    bool dijkstra(i32 src, i32 dst) {
        fill(dist + 1, dist + node_cnt + 1, INF);
        fill(cur + 1, cur + node_cnt + 1, head[1]);
        dist[dst] = 0;
        pq.push(HeapNode(dst, 0));

        while (!pq.empty()) {
            i32 u = pq.top().id;
            pq.pop();
            if (visited[u]) continue;
            visited[u] = true;

            for (i32 i = head[u]; i; i = edge[i].next) {
                i32 v = edge[i].to;
                i64 w = tag[u] + edge[i ^ 1].cost - tag[v];
                if (edge[i ^ 1].cap && dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push(HeapNode(v, dist[v]));
                }
            }
        }

        for (i32 i = 1; i <= node_cnt; ++i)
            tag[i] = min(tag[i] + dist[i], (i64)INF);

        if (!visited[src]) return false;
        fill(visited + 1, visited + node_cnt + 1, false);
        return true;
    }

    i32 dfs(i32 u, i32 dst, i32 flow) {
        if (u == dst || !flow) return flow;
        i32 pushed = 0;
        visited[u] = true;

        for (i32& i = cur[u]; i; i = edge[i].next) {
            if (edge[i].cap) {
                i32 v = edge[i].to;
                i32 f;
                if (!visited[v] && tag[v] + edge[i].cost == tag[u] &&
                    (f = dfs(v, dst, min(flow, edge[i].cap)))) {
                    edge[i].cap -= f;
                    edge[i ^ 1].cap += f;
                    pushed += f;
                    flow -= f;
                    if (!flow) break;
                }
            }
        }

        visited[u] = false;
        return pushed;
    }

    i32 max_flow;
    i64 min_cost;

    void compute(i32 src, i32 dst) {
        while (dijkstra(src, dst)) {
            i32 f = dfs(src, dst, INF);
            max_flow += f;
            min_cost += (i64)f * tag[src];
        }
    }
}

i32 source = 1, sink = 2, n, m, k, c, d;

inline i32 node_id(i32 t, i32 x) { return t * n + x + 2; }

void construct_layer(i32 t) {
    node_cnt += n;

    for (i32 u = 1; u <= n; ++u) {
        for (i32 v : graph[u]) {
            for (i32 p = 1; p <= k; ++p) {
                connect(node_id(t, u), node_id(t + 1, v), 1, d * (2 * p - 1));
            }
        }
    }

    for (i32 u = 1; u <= n; ++u) {
        connect(node_id(t, u), node_id(t + 1, u), INF, 0);
    }

    connect(node_id(t + 1, 1), sink, INF, c * (t + 1));
}

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    node_cnt = n + 2;

    for (i32 i = 1; i <= k; ++i) {
        i32 a;
        scanf("%d", &a);
        connect(source, node_id(0, a), 1, 0);
    }

    for (i32 i = 1; i <= m; ++i) {
        i32 u, v;
        scanf("%d%d", &u, &v);
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    connect(node_id(0, 1), sink, INF, 0);

    for (i32 i = 0; i <= n + k; ++i) {
        construct_layer(i);
    }

    MinCostFlow::compute(source, sink);
    printf("%lld\n", MinCostFlow::min_cost);
    return 0;
}
